  function openDetail(e){state.selected=e;const commercial=isCommercializable(e),actions=mode?'<div class="detail-actions"><button class="button secondary" data-action="edit-selected">Editar</button><button class="button danger" data-action="delete-selected">Eliminar</button></div>':'';$('#detailContent').innerHTML=`<div style="--event-color:${colorFor(e.Tipo)}"><div class="detail-type">${esc(e.Tipo)}</div><h2 class="detail-title" id="detailTitle">${esc(e.Nombre)}</h2>${commercial?`<span class="status-pill ${e.Disponibilidad==='Cupo lleno'?'full':''}">${esc(e.Disponibilidad)}</span>`:''}<div class="detail-meta">${detailRows(e)}${e.Enlace?`<div class="detail-row"><span>↗</span><a class="detail-link" href="${esc(e.Enlace)}" target="_blank" rel="noopener noreferrer">Ver enlace</a></div>`:''}</div>${e.Descripcion?`<div class="detail-description">${esc(e.Descripcion)}</div>`:''}${actions}</div>`;$('#detailModal').hidden=false;lockBody(true)}
