  function openForm(e){if(!mode)return;$('#eventForm').reset();state.formTalents=list(e?.Talentos);state.formExecutives=list(e?.Ejecutivos);$('#formError').hidden=true;$('#eventId').value=e?.ID||'';$('#formTitle').textContent=e?'Editar evento':'Crear evento';$('#saveButton').textContent=e?'Guardar cambios':'Guardar evento';if(e){$('#eventType').value=e.Tipo||'';$('#eventName').value=e.Nombre||'';$('#eventSystem').value=e.Sistema||'';$('#startDate').value=e.Fecha_Inicio||'';$('#endDate').value=e.Fecha_Fin||'';$('#startTime').value=e.Hora_Inicio||'';$('#endTime').value=e.Hora_Fin||'';setChecked('hasHours',e.Hora_Inicio?'Sí':'No');$('#description').value=e.Descripcion||'';$('#eventLink').value=e.Enlace||'';setChecked('commercial',e.Comercializable);setChecked('availability',e.Disponibilidad)}renderChips();updateHours();updateAvailability();updateCount();$('#detailModal').hidden=true;$('#formModal').hidden=false;lockBody(true);setTimeout(()=>$('#eventType').focus(),0)}
